<?php
namespace App\Controllers\Customer;
use App\Core\Controller;use App\Helpers\CustomerAuth;
class Orders extends Controller {public function index():void{$this->handleCors();if(!$this->isGet())$this->error('Method not allowed',405);$u=$this->customer();$status=trim((string)$this->query('status',''));$sql='SELECT o.id,o.order_number,o.status,o.total,o.created_at,p.status payment_status,d.tracking_number,d.status delivery_status FROM vp_orders o LEFT JOIN vp_payments p ON p.order_id=o.id LEFT JOIN vp_order_deliveries d ON d.order_id=o.id WHERE o.customer_id=?';$params=[(int)$u['id']];if($status!==''){$sql.=' AND o.status=?';$params[]=$status;}$sql.=' ORDER BY o.created_at DESC';$this->success(['items'=>$this->db()->query($sql,$params)->result_array()?:[]],'Orders loaded');}public function show($id=null):void{$this->handleCors();if(!$this->isGet())$this->error('Method not allowed',405);$u=$this->customer();$o=$this->db()->query('SELECT o.*,p.status payment_status,p.payment_type,p.paid_at,d.tracking_number,d.status delivery_status,d.tracking_payload,d.shipped_at,d.delivered_at FROM vp_orders o LEFT JOIN vp_payments p ON p.order_id=o.id LEFT JOIN vp_order_deliveries d ON d.order_id=o.id WHERE o.id=? AND o.customer_id=? LIMIT 1',[(int)$id,(int)$u['id']])->row_array();if(!$o)$this->error('Order not found',404);$o['items']=$this->db()->query('SELECT product_name,selections_snapshot,quantity,unit_price,total_price FROM vp_order_items WHERE order_id=? ORDER BY id',[(int)$o['id']])->result_array()?:[];$o['recipient']=json_decode($o['recipient_snapshot'],true);$o['tracking']=json_decode($o['tracking_payload']??'',true);unset($o['recipient_snapshot'],$o['tracking_payload']);$this->success($o,'Order loaded');}private function customer():array{$u=CustomerAuth::user();if(!$u)$this->error('Unauthorized',401);return $u;}}
